def smallestSubsequence(s: str, k: int, letter: str, repetition: int) -> str:
    n = len(s)
    letter_count = s.count(letter)  # occurrences of letter in s[i:]
    need = repetition               # letters still needed beyond those in stack
    stack = []

    for i, c in enumerate(s):
        # Pop larger chars if we can still fill k chars and still reach repetition
        while (stack and stack[-1] > c
               and len(stack) + n - i > k
               and (stack[-1] != letter or letter_count > need)):
            if stack.pop() == letter:
                need += 1

        if len(stack) < k:
            if c == letter:
                stack.append(c)
                need -= 1
            elif k - len(stack) > need:
                # Enough room left to still place the needed letters
                stack.append(c)

        if c == letter:
            letter_count -= 1

    return ''.join(stack)
